    out = [row[:] for row in grid]
    colored = []
    blanks = []
    dirs = ((-1, 0), (1, 0), (0, -1), (0, 1))
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if all(grid[r + dr][c + dc] == 3 for dr, dc in dirs):
                color = grid[r][c]
                if color == 0:
                    blanks.append((r, c))
                elif color != 3:
                    colored.append((r, c, color))

    def ray(r, c, color, dr, dc):
        own_arms = {(r + ar, c + ac) for ar, ac in dirs}
        y, x = r + dr, c + dc
        while 0 <= y < h and 0 <= x < w:
            if grid[y][x] == 3 and (y, x) not in own_arms:
                break
            if grid[y][x] != 3:
                out[y][x] = color
            y += dr
            x += dc

    # Cast horizontal then vertical rays: vertical colors win at intersections.
    for r, c, color in colored:
        ray(r, c, color, 0, -1)
        ray(r, c, color, 0, 1)
    for r, c, color in colored:
        ray(r, c, color, -1, 0)
        ray(r, c, color, 1, 0)

    # An empty gray cross reserves its full row and column as blank.
    for r, c in blanks:
        for x in range(w):
            if grid[r][x] != 3:
                out[r][x] = 0
        for y in range(h):
            if grid[y][c] != 3:
                out[y][c] = 0
    return out
